import * as THREE from 'three';
import {updateProduceCamera} from './camera.js';
import {createProduceController,SEASON_LABELS,PRODUCE_LABELS} from './controller.js';
import {createProduceSession} from './session.js';
import {PRODUCE_BY_ID} from './layout.js';
import {produceCanWater} from '../state/produce.js';
import {calendarSeason} from '../state/produce-season.js';
import {RADIUS} from '../physics.js';
import {lineClear} from '../interactions.js';
/** Small host seam. Ordinary camera stays in control; the garden never owns a save writer. */
export function createProduceGameHost({getProgress,transact,canSave,getRoom,getView,getActors,getCollision,getCamera,getCameraTarget,isAllowed,ui,onActive=()=>{},doc=globalThis.document,win=globalThis.window,reduced=false}){
 const activityCamera=new THREE.OrthographicCamera();let root=null,disposed=false,sizeKey='';const listeners=[];let last='';const listen=(n,t,f)=>{n?.addEventListener(t,f);listeners.push([n,t,f])};
 const controller=createProduceController({getProgress,transact,canSave,getRoom,getSceneEpoch:()=>getView(),isAllowed:()=>!doc.hidden&&doc.hasFocus?.()!==false&&isAllowed(),createSession:({nodeId,kind})=>createProduceSession({...getActors(),zoneRoot:getView().root,produceView:getView().produceView,nodeId,kind,reduced}),onChange:render});
 function render(s){if(!s){root?.remove();root=null;last='';sizeKey='';onActive(false);return;}if(!root){root=doc.createElement('section');root.className='produce-controls';root.setAttribute('aria-label','계절 텃밭');root.innerHTML='<strong data-produce-title></strong><p data-produce-season></p><p data-produce-status role="status" aria-live="polite"></p><button data-produce-start type="button"></button><label>놀이 계절 <select data-produce-season-choice></select></label><p class="produce-note">한국 달력을 따르거나 놀이 계절을 직접 골라요. 기다릴 필요 없이 물을 주면 자라요. 익은 작물과 모은 재료는 계속 남아요.</p><button data-produce-close type="button">산책으로 돌아가기</button>';const select=root.querySelector('select');for(const [value,label]of Object.entries(SEASON_LABELS)){const option=doc.createElement('option');option.value=value;option.textContent=label;select.append(option);}root.querySelector('[data-produce-start]').addEventListener('click',()=>controller.start());root.querySelector('[data-produce-close]').addEventListener('click',()=>controller.cancel());select.addEventListener('change',()=>controller.setSeason(select.value));root.addEventListener('keydown',e=>{if(e.repeat&&['Enter','Space'].includes(e.code))e.preventDefault()});doc.body.append(root);onActive(true);}
  const key=JSON.stringify([s.phase,s.ready,s.notice,s.season,s.canStart,s.readOnly,s.capped]);if(key===last)return;last=key;root.querySelector('[data-produce-title]').textContent=s.label+(PRODUCE_BY_ID[s.nodeId].kind==='tree'?' 나무':' 텃밭');root.querySelector('[data-produce-season]').textContent=`${SEASON_LABELS[s.season]}${s.season==='calendar'?' · '+SEASON_LABELS[s.calendarSeason].replace('놀이 ',''):''} · 돌보기 계절: ${s.allowedSeasons.map(x=>SEASON_LABELS[x].replace('놀이 ','')).join('·')}`;root.querySelector('[data-produce-status]').textContent=s.notice|| (s.readOnly?'둘러보기 모드예요. 저장할 수 있을 때 돌보고 수확해요':s.capped?'재료가방에 많이 모았어요. 이 작물은 그대로 둘게요':s.phase==='acting'?(s.kind==='water'?'도름이가 천천히 물을 줘요':'손으로 따서 바구니에 담아요'):s.ready?'잘 익었어요. 계절이 바뀌어도 수확할 수 있어요':s.canStart?'물을 주고 직접 돌봐요':'이 작물의 놀이 계절을 골라 돌볼 수 있어요');const button=root.querySelector('[data-produce-start]');button.disabled=!s.canStart;button.textContent=s.phase==='done'?'돌보기를 마쳤어요':s.phase==='failed'?'재료를 그대로 보관했어요':s.ready?`${s.label} 2개 수확하기`:'물 주기';root.querySelector('select').value=s.season;root.querySelector('select').disabled=s.phase!=='idle'||s.readOnly;
 }
 function cancel(reason){controller.cancel(reason)}
 listen(win,'blur',()=>cancel('blur'));listen(doc,'visibilitychange',()=>{if(doc.hidden)cancel('hidden')});listen(win,'pagehide',()=>cancel('pagehide'));listen(win,'pageshow',e=>{if(e.persisted)cancel('bfcache')});listen(win,'pointercancel',()=>cancel('pointercancel'));listen(win,'keydown',e=>{if(e.code==='Escape'&&controller.active){e.preventDefault();cancel('escape')}});
 return {open(target){if(disposed||getRoom()!=='park'||!PRODUCE_BY_ID[target.produceNodeId])return false;const p=getActors().player.position,n=PRODUCE_BY_ID[target.produceNodeId];if(!lineClear(getCollision(),p,n.approach,RADIUS)){ui.toast('작물 앞의 빈 길로 조금 더 와 주세요');return false;}return controller.open(n.id)},decorate(target){if(!target?.produceNodeId)return target;const p=getProgress(),n=p.produce?.nodes[target.produceNodeId],f=PRODUCE_BY_ID[target.produceNodeId];if(!n)return null;return {...target,label:PRODUCE_LABELS[f.species]+(n.phase==='ready'?' 2개 수확하기':produceCanWater(p.produce,f.id,calendarSeason())?' 물 주기':' · 놀이 계절 고르기')}},tick(dt){controller.tick(dt)},resize(w,h,resize){const key=w+'|'+h;if(key!==sizeKey){sizeKey=key;resize();}},get camera(){const s=controller.snapshot();return s&&getCamera?updateProduceCamera(activityCamera,getCamera(),getCameraTarget(),PRODUCE_BY_ID[s.nodeId]):null},cancel,get active(){return controller.active},snapshot:()=>controller.snapshot(),dispose(){if(disposed)return;disposed=true;controller.dispose();for(const[n,t,f]of listeners)n?.removeEventListener(t,f)}};
}
